using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class CreatureAttemptChecks {
 static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void VerifyModel(){
  var h=new HybridState();Check(h.Valid()&&h.attempts==null,"Legacy attempts initialized");for(int i=0;i<4;i++){Check(h.FailedAttempt(CreatureAction.PlayWithToy,"toy",AttemptMode.Ordinary,Vector3.zero,"Target unreachable"),"Failure not stored");var a=h.Attempt(CreatureAction.PlayWithToy,"toy",AttemptMode.Ordinary);Check(a.retryAt-h.time==15*(1<<i)&&!h.AttemptAllowed(a.action,a.target,a.mode,Vector3.zero)&&!h.FailedAttempt(a.action,a.target,a.mode,Vector3.zero,a.reason),"Backoff / dedup failed");h.time=a.retryAt;}
  Check(h.AttemptAllowed(CreatureAction.PlayWithToy,"toy",AttemptMode.Echo,Vector3.zero),"Ordinary play blocked separate echo");h.FailedAttempt(CreatureAction.PlayWithToy,"toy",AttemptMode.Ordinary,Vector3.zero,"Target unreachable");var moved=Vector3.right*9;Check(h.AttemptAllowed(CreatureAction.PlayWithToy,"toy",AttemptMode.Ordinary,moved),"Moved target not reconsidered");h.FailedAttempt(CreatureAction.PlayWithToy,"toy",AttemptMode.Ordinary,moved,"Target unreachable");Check(h.Attempt(CreatureAction.PlayWithToy,"toy",AttemptMode.Ordinary).retryAt-h.time==15,"Changed location retained old failure streak");h.CompletedAttempt(CreatureAction.PlayWithToy,"toy",AttemptMode.Ordinary,moved);Check(h.AttemptAllowed(CreatureAction.PlayWithToy,"toy",AttemptMode.Ordinary,moved)&&h.Attempt(CreatureAction.PlayWithToy,"toy",AttemptMode.Ordinary).streak==0,"Confirmed success did not clear backoff");
  for(int i=0;i<40;i++){h.time++;h.CompletedAttempt(CreatureAction.InvestigateObject,"object-"+i,AttemptMode.Ordinary,Vector3.zero);}Check(h.attempts.Length==32&&h.Valid()&&JsonUtility.FromJson<HybridState>(JsonUtility.ToJson(h)).Valid(),"Bounded attempt memory failed round trip");h.attempts[0].point.x=float.NaN;Check(!h.Valid(),"Nonfinite attempt point accepted");
  var skill=new BuildingPractice();float time=skill.PlacementSeconds;for(int i=0;i<20;i++)skill.Confirm(false);Check(skill.PlacementSeconds<time&&skill.control>.5f,"Practice failed to improve existing physical execution");var ball=new GentleBallSkill();for(int i=0;i<20;i++)ball.Practice(i*13);float control=ball.control;for(int i=0;i<6;i++)ball.Reinforce(false);Check(ball.control==control&&ball.preference<.1f,"Discouragement erased learned physical skill");
  var legacy=new SliceState();string before=JsonUtility.ToJson(legacy);for(int i=0;i<3;i++)CreationBookText.Read(legacy,CreationBookSection.Creature,i);Check(before==JsonUtility.ToJson(legacy),"Reading skill/attempt pages initialized history");Debug.Log("BWVR_CREATURE_ATTEMPT_MODEL_PASS: deterministic bounded backoff, distinct modes, location change, success reset, save validation, practice versus willingness and pure Book");
 }
 public static void VerifyRuntime(){
  Check(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var god=slice.GetComponentInChildren<CreatureHybrid>();var nav=god.GetComponent<IslandNavigator>().world;Check(!nav.TreeNavigationPending,"Wait for navigation");var field=typeof(QuestSlice).GetField("state",F);var original=(SliceState)field.GetValue(slice);var gp=god.transform.position;var gr=god.transform.rotation;var people=slice.GetComponentsInChildren<VillagerSocial>();var held=people.Select(p=>p.GetComponent<CarryItem>().held).ToArray();var toy=god.Targets.First(t=>t.affordance!=null&&t.affordance.kind==CreatureAffordance.Kind.Chime&&t.affordance.host==null);var at=toy.transform.position;var rotation=toy.transform.rotation;var item=toy.GetComponent<CarryItem>();bool wasHeld=item.held;int discoveries=toy.affordance.discoveries;var cooldowns=god.Targets.Where(t=>t.affordance!=null).ToDictionary(t=>t.affordance,t=>t.affordance.cooldown);var ideas=slice.GetComponentsInChildren<ConstructionInspiration>();var active=ideas.Select(i=>i.gameObject.activeSelf).ToArray();var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true,water=100,crops=100,hunger=.05f};
  try{
   god.Interrupt("Attempt QA");field.SetValue(slice,test);god.NewSeason();slice.SetSanctuaryOpen(false);foreach(var person in people)person.GetComponent<CarryItem>().held=true;foreach(var idea in ideas)idea.gameObject.SetActive(false);foreach(var a in cooldowns.Keys)a.cooldown=100000;toy.affordance.cooldown=0;item.held=false;bool unreachable=false;for(int radius=30;radius<=330&&!unreachable;radius+=20)for(int angle=0;angle<16&&!unreachable;angle++){toy.transform.position=god.transform.position+Quaternion.Euler(0,angle*22.5f,0)*Vector3.forward*nav.Scale*radius;unreachable=!god.CanReach(toy);}Physics.SyncTransforms();Check(unreachable,"No unreachable target within perception range");
   for(int i=0;i<30&&test.Hybrid.Attempt(CreatureAction.PlayWithToy,toy.id,AttemptMode.Ordinary)==null;i++)god.Tick(.05f);var memory=test.Hybrid.Attempt(CreatureAction.PlayWithToy,toy.id,AttemptMode.Ordinary);Check(memory!=null&&memory.failures==1&&memory.completions==0&&god.Owner==CreatureHybrid.ActionOwner.None,"Actual unreachable selection not recorded / retained ownership");for(int i=0;i<80;i++)god.Tick(.05f);Check(memory.failures==1,"Repeated perception retried deferred target");god.Perceive();var candidates=(System.Collections.Generic.List<CreatureCandidate>)typeof(CreatureHybrid).GetField("candidates",F).GetValue(god);Check(candidates.Any(c=>c.target==toy.id&&!c.feasible&&c.reason.Length>0),"Remembered failure missing from candidate feasibility");
   test.paused=true;string paused=JsonUtility.ToJson(test);god.Tick(30);Check(paused==JsonUtility.ToJson(test),"Pause advanced attempt timing");test.paused=false;typeof(QuestSlice).GetMethod("Save",F).Invoke(slice,null);typeof(QuestSlice).GetMethod("Load",F).Invoke(slice,null);test=(SliceState)field.GetValue(slice);god.NewSeason();toy.affordance.cooldown=0;foreach(var a in cooldowns.Keys)if(a!=toy.affordance)a.cooldown=100000;Check(test.Valid()&&!test.Hybrid.AttemptAllowed(CreatureAction.PlayWithToy,toy.id,AttemptMode.Ordinary,nav.ToNav(toy.transform.position)),"Native resume lost backoff");
   var lane=slice.GetComponentInChildren<BeachBall>().Bowling;Check(nav.Sample(lane.Start,nav.creature,5,out var start),"No reachable creature stage");god.transform.position=nav.ProjectFoot(start,nav.creature);god.GetComponent<IslandNavigator>().ResetRoute();Check(nav.Sample(start+lane.Right*nav.Scale*14,nav.creature,5,out var spot),"No repaired target position");toy.transform.position=nav.ProjectFoot(spot,nav.creature)+Vector3.up*nav.Scale*2;god.transform.LookAt(new Vector3(toy.transform.position.x,god.transform.position.y,toy.transform.position.z));Physics.SyncTransforms();god.Perceive();Check(candidates.Any(c=>c.target==toy.id&&c.feasible)&&test.Hybrid.time<test.Hybrid.Attempt(CreatureAction.PlayWithToy,toy.id,AttemptMode.Ordinary).retryAt,"Changed target did not reopen before timer");
   for(int i=0;i<1600&&test.Hybrid.Attempt(CreatureAction.PlayWithToy,toy.id,AttemptMode.Ordinary).completions==0;i++)god.Tick(.05f);memory=test.Hybrid.Attempt(CreatureAction.PlayWithToy,toy.id,AttemptMode.Ordinary);Check(memory.completions==1&&memory.failures==1&&memory.streak==0&&!item.held&&god.Owner==CreatureHybrid.ActionOwner.None,"Repositioned toy did not physically complete and release");float preference=test.playPreference;Check(god.Feedback(true)&&test.playPreference>preference&&memory.completions==1&&memory.failures==1,"Praise changed attempt outcome instead of willingness");
   god.Interrupt("Interruption check");toy.affordance.cooldown=0;for(int i=0;i<100&&god.Owner!=CreatureHybrid.ActionOwner.Curiosity;i++)god.Tick(.05f);Check(god.Owner==CreatureHybrid.ActionOwner.Curiosity,"No active attempt for interruption");god.Interrupt("Player picked up the creature");Check(memory.failures==1&&!item.held&&god.Owner==CreatureHybrid.ActionOwner.None,"Player interruption learned failure / stranded cargo");Check(JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test)).Valid(),"Completed attempt save invalid");Debug.Log("BWVR_CREATURE_ATTEMPT_RUNTIME_PASS: actual unreachable choice, bounded retry exclusion, pause, native Save/Load, target reposition before expiry, native physical toy completion/cleanup, preference isolation and unpunished interruption");
  }finally{god.Interrupt("Attempt QA finished");item.held=wasHeld;toy.GetComponent<Collider>().enabled=!wasHeld;toy.transform.SetPositionAndRotation(at,rotation);toy.affordance.discoveries=discoveries;field.SetValue(slice,original);god.NewSeason();foreach(var pair in cooldowns)pair.Key.cooldown=pair.Value;for(int i=0;i<ideas.Length;i++)ideas[i].gameObject.SetActive(active[i]);for(int i=0;i<people.Length;i++)people[i].GetComponent<CarryItem>().held=held[i];god.transform.SetPositionAndRotation(gp,gr);god.GetComponent<IslandNavigator>().ResetRoute();Physics.SyncTransforms();}
 }
}
}
